extension Document: SyncRecord {
    static var syncType: String { "document" }
    static var alwaysShared: Bool { false }
    static var followsParent: Bool { false }
    static func blank() -> Document { Document(title: "", type: .other, fileURL: "") }
    var syncParent: (any SyncRecord)? { nil }
    var syncFiles: [SyncFile] { [(fileURL.isEmpty ? nil : SyncFile(field: "fileURL", name: URL(fileURLWithPath: fileURL).lastPathComponent, kind: .document))].compactMap { $0 } }

    func syncFields() -> [String: Any] {
        var d: [String: Any] = [:]
        d["title"] = title
        d["type"] = type.rawValue
        d["fileURL"] = fileURL.isEmpty ? "" : URL(fileURLWithPath: fileURL).lastPathComponent
        d["ocrText"] = ocrText
        d["createdAt"] = createdAt
        d["expiryDate"] = expiryDate ?? NSNull()
        d["warrantyId"] = warranty?.syncIdOrNull ?? NSNull()
        d["billId"] = bill?.syncIdOrNull ?? NSNull()
        d["projectId"] = project?.syncIdOrNull ?? NSNull()
        d["maintenanceId"] = maintenance?.syncIdOrNull ?? NSNull()
        d["assetId"] = asset?.syncIdOrNull ?? NSNull()
        d["roomId"] = room?.syncIdOrNull ?? NSNull()
        return d
    }

    func applySyncFields(_ d: SyncData) {
        if let v = d.string("title") { title = v }
        if let v = d.string("type"), let e = DocumentType(rawValue: v) { type = e }
        if let v = d.string("fileURL") { let local = fileURL.isEmpty ? "" : URL(fileURLWithPath: fileURL).lastPathComponent; if v != local { fileURL = v.isEmpty ? "" : DocumentStorage.directory.appendingPathComponent(v).path } }
        if let v = d.string("ocrText") { ocrText = v }
        if let v = d.date("createdAt") { createdAt = v }
        if d.has("expiryDate") { expiryDate = d.date("expiryDate") }
    }

    func applySyncRefs(_ d: SyncData, _ r: SyncResolver) {
        if d.has("warrantyId") { warranty = r.find(Warranty.self, d.string("warrantyId")) }
        if d.has("billId") { bill = r.find(Bill.self, d.string("billId")) }
        if d.has("projectId") { project = r.find(Project.self, d.string("projectId")) }
        if d.has("maintenanceId") { maintenance = r.find(Maintenance.self, d.string("maintenanceId")) }
        if d.has("assetId") { asset = r.find(Asset.self, d.string("assetId")) }
        if d.has("roomId") { room = r.find(Room.self, d.string("roomId")) }
    }
}

